import { useTranslation } from 'react-i18next';
import { Button, IconButton } from '@carbon/react';
import { PrinterIcon, showModal, UserHasAccess, useLayoutType, type Visit } from '@openmrs/esm-framework';

interface PrintVisitSummaryActionButtonProps {
  visit: Visit;
  patient: fhir.Patient;

  /**
   * Provided via the `visit-detail-overview-actions` extension slot state. The visit
   * history table passes `compact: true` to render an icon-only button; hosts that
   * omit it get a full button with a text label.
   */
  compact?: boolean;
}

const PrintVisitSummaryActionButton: React.FC<PrintVisitSummaryActionButtonProps> = ({ visit, compact }) => {
  const { t } = useTranslation();
  const isTablet = useLayoutType() === 'tablet';
  const responsiveSize = isTablet ? 'lg' : 'sm';

  const openPreviewModal = useCallback(() => {
    const dispose = showModal('print-visit-summary-modal', {
      visitUuid: visit.uuid,
      closeModal: () => dispose(),
    });
  }, [visit?.uuid]);

  if (!visit?.uuid) {
    return null;
  }

  return (
    <UserHasAccess privilege="App: Can generate a Visit Summary">
      {compact ? (
        <IconButton
          onClick={openPreviewModal}
          label={t('printVisitSummary', 'Print visit summary')}
          size={responsiveSize}
          kind="ghost"
          align="top-end"
        >
          <PrinterIcon size={16} />
        </IconButton>
      ) : (
        <Button onClick={openPreviewModal} kind="ghost" renderIcon={PrinterIcon} size={responsiveSize}>
          {t('printVisitSummary', 'Print visit summary')}
        </Button>
      )}
    </UserHasAccess>
  );
};

export default PrintVisitSummaryActionButton;
